namespace ks {
class NativeMidiControlService final {
public:
 using Kind=MidiControlTask::Kind;enum class Component{Control,Lookup,Modulation,Sweep,Release,Keys,Pedal};
 struct Input{uint32_t payload=0,patch=0,field=0;uint8_t patchPart=0;};struct Effect{bool read=false,write=false;};
 struct Summary{Kind kind=Kind::Control;Input input{};bool tail=false,modulated=false,swept=false,released=false,cleared=false,pedaled=false;};
 NativeMidiControlService(Kind k,Input i):task_(k){summary_.kind=k;summary_.input=i;}
 bool complete()const{return complete_;}bool critical()const{return component_==Component::Pedal&&pedal_&&pedal_->critical();}Component component()const{return component_;}uint32_t components()const{return components_;}const Effect&effect()const{return effect_;}const Summary&summary()const{return summary_;}const MidiControlTask&controlTask()const{return task_;}
 const NativeVoiceModulationService*modulationOutcome()const{return summary_.modulated?&*modulation_:nullptr;}const NativeVoiceSweepService*sweepOutcome()const{return summary_.swept?&*sweep_:nullptr;}const NativeVoiceReleaseService*releaseOutcome()const{return summary_.released?&*release_:nullptr;}const NativeKeyService*keyOutcome()const{return summary_.cleared?&*keys_:nullptr;}const NativePedalControlService*pedalOutcome()const{return summary_.pedaled?&*pedal_:nullptr;}
 template<class T>const T*task()const{if(complete_)return nullptr;if constexpr(std::is_same_v<T,MidiControlTask>)return component_==Component::Control?&task_:nullptr;else if constexpr(std::is_same_v<T,PartLookupTask>){if(component_==Component::Lookup)return &*lookup_;return nested<T>();}else if constexpr(std::is_same_v<T,NativeVoiceModulationService>)return component_==Component::Modulation?&*modulation_:nullptr;else if constexpr(std::is_same_v<T,NativeVoiceSweepService>)return component_==Component::Sweep?&*sweep_:nullptr;else if constexpr(std::is_same_v<T,NativeVoiceReleaseService>)return component_==Component::Release?&*release_:nullptr;else if constexpr(std::is_same_v<T,NativeKeyService>)return component_==Component::Keys?&*keys_:nullptr;else if constexpr(std::is_same_v<T,NativePedalControlService>)return component_==Component::Pedal?&*pedal_:nullptr;else return nested<T>();}
 unsigned nextClocks(int previous=-1)const{if(complete_)return 0;switch(component_){case Component::Control:return task_.nextClocks(task_.publication()?byteClock(0x160d2u+334*task_.part()+331,previous):3);case Component::Lookup:return lookup_->stage()==PartLookupTask::Stage::Complete?17:lookup_->nextClocks();case Component::Modulation:return modulation_->nextClocks(previous);case Component::Sweep:return sweep_->nextClocks(previous);case Component::Release:return release_->nextClocks(previous);case Component::Keys:return keys_->nextClocks(previous);case Component::Pedal:return pedal_->nextClocks(previous);}return 0;}
 template<class R,class W,class Resolver>unsigned advanceBefore(unsigned budget,R&&read,W&&write,Resolver&&resolver,int previous=-1){const auto cost=nextClocks(previous);if(!cost||cost>budget)return 0;effect_={};
  const auto done=[&]{if(summary_.tail)complete_=true;else{task_.resumeChild();select(Component::Control);}};
  if(component_==Component::Lookup){if(lookup_->stage()==PartLookupTask::Stage::Complete){task_.resumePart(lookup_->index());lookup_.reset();effect_.read=true;select(Component::Control);}else lookup_->advanceBefore(cost,[&](auto){return read(0x17526,cost);});return cost;}
  if(component_==Component::Modulation){modulation_->advanceBefore(cost,read,write,previous);effect_={modulation_->effect().read,modulation_->effect().write};if(modulation_->complete()){summary_.modulated=true;done();}return cost;}
  if(component_==Component::Sweep){sweep_->advanceBefore(cost,read,write,previous);effect_={sweep_->effect().read,sweep_->effect().write};if(sweep_->complete()){summary_.swept=true;done();}return cost;}
  if(component_==Component::Release){release_->advanceBefore(cost,read,write,previous);effect_={release_->effect().read,release_->effect().write};if(release_->complete()){summary_.released=true;done();}return cost;}
  if(component_==Component::Keys){keys_->advanceBefore(cost,read,write,previous);effect_={keys_->effect().read,keys_->effect().write};if(keys_->complete()){summary_.cleared=true;done();}return cost;}
  if(component_==Component::Pedal){pedal_->advanceBefore(cost,read,write,resolver,previous);effect_={pedal_->effect().read,pedal_->effect().write};if(pedal_->complete()){summary_.pedaled=true;done();}return cost;}
  using T=MidiControlTask;using S=T::Stage;const auto stage=task_.stage();task_.advanceBefore(cost,[&](T::Read r)->uint32_t{switch(r){case T::Read::EventFirst:return read(summary_.input.payload&0xffffff,cost);case T::Read::EventSecond:return read((summary_.input.payload+1)&0xffffff,cost);case T::Read::ExpressionController:return read((summary_.input.patch+177)&0xffffff,cost);default:return task_.value();}},[&](unsigned at,uint8_t v){write(0x160d2u+334*task_.part()+at,v,cost);},[&](unsigned at){return byteClock(0x160d2u+334*task_.part()+at,previous);});
  switch(stage){case S::DispatchPitch:case S::DispatchPressure:case S::DispatchPart:case S::DispatchSound:case S::DispatchRelease:case S::DispatchHeldReset:effect_.write=true;break;case S::FinishPitch:case S::FinishPressure:case S::FinishBank:case S::FinishSound:case S::FinishReset:case S::FinishNotes:effect_.read=true;break;default:break;}
  if(task_.awaitingPart()){lookup_.emplace(PartLookupTask::Layout::Parameters);select(Component::Lookup);}else if(task_.awaitingChild()){switch(task_.stage()){case S::AwaitPitch:case S::AwaitPressure:modulation_.emplace(task_.stage()==S::AwaitPitch?NativeVoiceModulationService::Kind::Cutoff:NativeVoiceModulationService::Kind::Square,NativeVoiceModulationService::Input{task_.argument()});select(Component::Modulation);break;case S::AwaitSound:sweep_.emplace(NativeVoiceSweepService::Kind::ReleaseAll);select(Component::Sweep);break;case S::AwaitRelease:release_.emplace(VoiceReleaseTask::Mode::Part);select(Component::Release);break;case S::AwaitHeldReset:keys_.emplace(NativeKeyService::Kind::ResetHeld);select(Component::Keys);break;default:throw std::logic_error("Unexpected MIDI control child");}}else if(task_.handoff()){summary_.tail=true;if(task_.stage()==S::HandoffPedal){pedal_.emplace(NativePedalControlService::Kind::Controller,NativePedalControlService::Input{task_.controller(),task_.value(),summary_.input.patchPart,summary_.input.field});select(Component::Pedal);}else{modulation_.emplace(task_.stage()==S::HandoffWheel?NativeVoiceModulationService::Kind::First:NativeVoiceModulationService::Kind::Second,NativeVoiceModulationService::Input{task_.argument()});select(Component::Modulation);}}else if(task_.complete())complete_=true;return cost;
 }
private:
 template<class T>const T*nested()const{switch(component_){case Component::Modulation:return modulation_->template task<T>();case Component::Sweep:return sweep_->template task<T>();case Component::Release:return release_->template task<T>();case Component::Keys:return keys_->template task<T>();case Component::Pedal:return pedal_->template task<T>();default:return nullptr;}}static unsigned byteClock(uint32_t a,int p){return a<0x400000&&!(p&1)&&a==(uint32_t(p)|1u)?0:3;}void select(Component c){component_=c;components_|=1u<<unsigned(c);}
 MidiControlTask task_;bool complete_=false;Component component_=Component::Control;uint32_t components_=1;Effect effect_{};Summary summary_{};std::optional<PartLookupTask>lookup_;std::optional<NativeVoiceModulationService>modulation_;std::optional<NativeVoiceSweepService>sweep_;std::optional<NativeVoiceReleaseService>release_;std::optional<NativeKeyService>keys_;std::optional<NativePedalControlService>pedal_;
};
}
